<?php
// ارسال با پیک/اسنپ/پست/تیپاکس…: ثبت، رهگیری، هزینه، وضعیت + پیک‌ها + لینکِ ثبتِ نشانی
$f = report_filters($_GET + ['from' => jdate(date('Y-m-d', strtotime('-30 day')), false, false)]);
$st = isset(ship_statuses()[$_GET['st'] ?? '']) ? $_GET['st'] : '';
$cs = ui_opts("SELECT id, CONCAT(name, COALESCE(CONCAT(' — ', mobile), '')) name FROM couriers WHERE active=1 ORDER BY name"); $bo = ui_opts("SELECT id, title name FROM bank_accounts WHERE active=1");
echo '<div class="cols">' . ui_card('ثبتِ ارسالِ تازه', ui_form('ship_save', ['sale_number' => ['شمارهٔ فروش (اختیاری)', 'ltr'], 'customer_id' => ['مشتری', 'cpick'], 'carrier' => ['شرکت/روش', 'select', 1, ship_carriers()], 'courier_id' => ['پیک', 'select', 0, $cs],
    'tracking' => ['کدِ رهگیری/سفارش', 'ltr'], 'receiver_name' => ['گیرنده', 'text'], 'receiver_mobile' => ['موبایلِ گیرنده', 'ltr'], 'address' => ['نشانی (خالی = نشانیِ پیش‌فرضِ مشتری)', 'textarea'], 'postal_code' => ['کدِ پستی', 'ltr'],
    'cost' => ['هزینهٔ ارسال', 'money'], 'payer' => ['پرداخت‌کننده', 'select', 1, ship_payers()], 'paid_from' => ['هزینه از', 'select', 0, ['cash' => 'صندوق', 'bank' => 'بانک']], 'bank_account_id' => ['حساب', 'select', 0, $bo], 'cod_amount' => ['دریافت در محل (COD)', 'money'], 'note' => ['یادداشت', 'text'], 'sms' => ['پیامکِ رهگیری به گیرنده', 'check']], ['sms' => 1], ['submit' => 'ثبتِ ارسال']))
    . ui_card('لینکِ ثبتِ نشانی برای مشتری', '<p class="muted">مشتری با این لینک (۷ روز) بی‌ورود نشانی و موقعیتش را می‌زند و در دفترچهٔ نشانی‌اش ذخیره می‌شود. اگر مشتری نباشد، با همین موبایل ساخته می‌شود.</p>'
        . ui_form('addr_link', ['customer_id' => ['مشتری', 'cpick'], 'mobile' => ['یا موبایلِ تازه', 'ltr'], 'name' => ['نام', 'text'], 'postal' => ['نشانیِ پستیِ کامل و کدِ پستی هم لازم است', 'check'], 'sms' => ['با پیامک بفرست', 'check']], ['sms' => 1], ['submit' => 'ساختنِ لینک', 'then' => 'none'])) . '</div>';
echo '<form class="filters"><input type="hidden" name="p" value="shipments"><label>از<input class="jd" name="from" value="' . h(jdate($f['from'])) . '"></label><label>تا<input class="jd" name="to" value="' . h(jdate($f['to'])) . '"></label><label>وضعیت<select name="st"><option value="">همه</option>'
    . implode('', array_map(fn($k, $t) => '<option value="' . $k . '"' . ($k === $st ? ' selected' : '') . '>' . h($t) . '</option>', array_keys(ship_statuses()), ship_statuses())) . '</select></label><button class="btn">نمایش</button></form>';
$next = ['registered' => 'picked', 'picked' => 'delivered'];
echo ui_card('ارسال‌ها', ui_table(['created_at' => ['زمان', 'datetime'], 'carrier' => ['روش', fn($r) => h(ship_carriers()[$r['carrier']] ?? $r['carrier']) . ($r['courier'] ? '<br><small>' . h($r['courier']) . '</small>' : '')], 'tracking' => ['رهگیری', 'code'],
    'sale_number' => ['فروش', fn($r) => $r['sale_id'] ? '<a href="' . h(page_url('sale', ['id' => $r['sale_id']])) . '">' . h(fa_num((string)$r['sale_number'])) . '</a>' : '—'], 'receiver_name' => ['گیرنده', fn($r) => h((string)$r['receiver_name']) . '<br><small>' . h(fa_num((string)$r['receiver_mobile'])) . '</small>'],
    'address' => ['نشانی', fn($r) => h(mb_substr((string)$r['address'], 0, 80)) . ($r['lat'] ? ' <a target="_blank" href="https://www.openstreetmap.org/?mlat=' . $r['lat'] . '&mlon=' . $r['lng'] . '#map=17/' . $r['lat'] . '/' . $r['lng'] . '">📍</a>' : '')],
    'cost' => ['هزینه', fn($r) => fa_money($r['cost']) . '<br><small>' . h(ship_payers()[$r['payer']] ?? '') . '</small>'], 'cod_amount' => ['COD', 'money'],
    'status' => ['وضعیت', fn($r) => ui_badge(ship_statuses()[$r['status']] ?? $r['status'], $r['status'] === 'delivered' ? 'ok' : (in_array($r['status'], ['returned', 'canceled'], true) ? 'err' : 'warn'))],
    'a' => ['', fn($r) => (isset($next[$r['status']]) ? ui_btn_api(ship_statuses()[$next[$r['status']]], 'ship_status', ['id' => $r['id'], 'status' => $next[$r['status']]], ['class' => 'sm']) . ' ' : '') . (!in_array($r['status'], ['delivered', 'returned', 'canceled'], true) ? ui_btn_api('برگشت', 'ship_status', ['id' => $r['id'], 'status' => 'returned'], ['class' => 'sm', 'confirm' => 'برگشت خورد؟']) . ' ' . ui_btn_api('لغو', 'ship_status', ['id' => $r['id'], 'status' => 'canceled'], ['class' => 'sm', 'confirm' => 'لغو شود؟']) . ' ' : '') . ($r['receiver_mobile'] ? ui_btn_api('پیامک', 'ship_sms', ['id' => $r['id']], ['class' => 'sm']) : '')]],
    ship_list(['status' => $st, 'from' => $f['from'], 'to' => $f['to']]), ['filter' => 1, 'empty' => 'ارسالی نیست.']));
echo ui_card('پیک‌ها', ui_table(['name' => 'نام', 'mobile' => ['موبایل', 'num'], 'carrier' => ['نوع', fn($r) => h(ship_carriers()[$r['carrier']] ?? $r['carrier'])], 'active' => ['', fn($r) => $r['active'] ? '' : ui_badge('غیرفعال')]], rows("SELECT * FROM couriers ORDER BY active DESC, name"))
    . ui_form('courier_save', ['name' => ['نامِ پیک', 'text', 1], 'mobile' => ['موبایل', 'ltr'], 'carrier' => ['نوع', 'select', 1, ship_carriers()]], [], ['submit' => 'افزودنِ پیک']));
